# which expected cells aren't covered by bbox or gap?
def coverage(pts,bg,i_,o_):
    H,W=len(i_),len(i_[0])
    cov=set()
    for color in set(x for row in i_ for x in row if x!=bg):
        P=[(r,c) for r in range(H) for c in range(W) if i_[r][c]==color]
        for r in range(H):
            cs=sorted(c for rc,c in P if rc==r)
            for a,b in zip(cs,cs[1:]):
                for cc in range(a+1,b): cov.add((r,cc))
        for c in range(W):
            rs=sorted(r for r,cc in P if cc==c)
            for a,b in zip(rs,rs[1:]):
                for rr in range(a+1,b): cov.add((rr,c))
        # bbox perimeter
        r0=min(p[0] for p in P); r1=max(p[0] for p in P)
        c0=min(p[1] for p in P); c1=max(p[1] for p in P)
        for rr in range(r0,r1+1):
            for cc in (c0,c1): cov.add((rr,cc))
        for cc in range(c0,c1+1):
            for rr in (r0,r1): cov.add((rr,cc))
    return cov
