def comps(i,bg):
    H,W=len(i),len(i[0]); seen=[[False]*W for _ in range(H)]
    out=[]
    for r in range(H):
        for c in range(W):
            if i[r][c]!=bg and not seen[r][c]:
                col=i[r][c]; st=c;q=deque([(r,c)])
                seen[r][c]=True; comp=[]
                while q:
                    a,b=q.popleft(); comp.append((a,b))
                    for da,d b in [(1,0),(-1,0),(0,1),(0,-1)]:
